// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address to, uint8 count) public {
        // keep params admissible: non-empty recipient array, distinct-enough receivers
        uint256 n = bound(uint256(count), 1, 20);
        address[] memory tos = new address[](n);
        for (uint256 i = 0; i < n; i++) {
            tos[i] = address(uint160(uint256(uint160(to)) + i + 1));
        }
        // a permissive ERC20-like token that accepts transferFrom
        Token t = new Token();
        vm.prank(from);
        bool ok = c.transfer(from, address(t), tos, 1);
        // Reference contract: transfer always returns true for a non-empty list.
        assertTrue(ok);
    }
}

contract Token {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
